INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 1, 'theory', 'Quiz: sets');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 1, 0, 'How does a set differ from a list?', '["Order matters in a set, but not in a list", "A set stores only the fact of membership: no order and no repeats", "A set always keeps its elements sorted", "It doesn''t: they are two names for the same structure"]', 1, 'A list is a contract about order and repeats, a set is only about membership: an element is either in or not. Hence the instant answer to the question "is there one of these here".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 1, 1, 'What does ¬(A ∪ B) equal by De Morgan''s laws?', '["¬A ∪ ¬B", "A ∩ B", "¬A ∩ ¬B", "¬(A ∩ B)"]', 2, 'Negation flips "or" into "and": it is not true that an element is in at least one set — so it is in neither. Symmetrically, ¬(A ∩ B) = ¬A ∪ ¬B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 1, 2, 'In a group, 20 people know English and 20 know German. Why might there not be 40 of them?', '["Because the cardinality of a union is always less than forty", "Because lists of languages cannot be united — only intersected", "Because languages are counted together only in a database", "Because some people know both languages and appeared in both lists"]', 3, 'The cardinality of a union equals the sum of the cardinalities minus the cardinality of the intersection: whoever knows both languages is counted in both groups. Naive addition is the classic double-counting mistake.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 1, 3, 'Why does a set of n elements have exactly 2ⁿ subsets?', '["Because each element can be taken or not taken — two independent choices for each of n elements", "Because subsets form Pascal''s triangle", "Because each element produces two new elements of the power set", "Because n is multiplied by the number of elements of the universe"]', 0, 'When building a subset you decide "take or not" for each of the n elements — by the product rule that gives 2ⁿ. Three elements give 8 subsets, ten give 1024; programmers know this from bit masks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 1, 4, 'What happens to the complement of a set A if you change the universe?', '["Nothing: the complement is a property of the set itself", "It becomes empty", "It changes, because the complement is taken relative to the chosen universe", "It turns into the intersection of A with the new universe"]', 2, 'The complement is everything outside A but inside the universe. Change the universe from "users of the system" to "all people" — and the complement becomes different, although A itself has not changed.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 2, 'theory', 'Quiz: relations and functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 2, 0, 'What is a relation between two sets from the point of view of set theory?', '["A subset of their Cartesian product", "Any function between them", "A table with unique keys", "A rule that assigns each element exactly one image"]', 0, 'A relation is simply a collection of pairs marked "related / not related", that is, a subset of the Cartesian product. A function is a special case with a strict contract, and a table in a relational database is the same relation — hence the word "relational".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 2, 1, 'Which three properties does an equivalence relation have?', '["Reflexivity, antisymmetry, transitivity", "Symmetry, transitivity, completeness", "Reflexivity, symmetry, transitivity", "Antisymmetry, transitivity, injectivity"]', 2, 'Equivalence is "equality by agreement": everyone is related to themselves, the link works in both directions and carries along a chain. A partial order differs in the second item — there it is antisymmetry.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 2, 2, 'What does an equivalence relation give on a set?', '["A linear order of all the elements", "A partition into non-overlapping classes of \"identical\" elements", "A directed graph without cycles", "An injection of the set into itself"]', 1, 'Equivalence cuts a set into classes: inside, everything is considered identical, and between classes there is no overlap. Grouping by a key in code is exactly this partition.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 2, 3, 'What does the word "partial" mean in "partial order"?', '["The order is defined only on part of the elements of the set", "There are pairs of elements that cannot be compared with each other at all", "The relation holds only for some of the operations", "The order works only in trees"]', 1, 'The order properties are defined on the whole set, but they do not require any two elements to be comparable. In a dependency tree two packages from different branches are incomparable — and that is normal; topological sorting helps stretch such an order into a line.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 2, 4, 'How does a bijection differ from an injection?', '["It doesn''t: they are synonyms", "A bijection does not require different outputs for different inputs", "A bijection allows several inputs with one output", "A bijection is an injection plus a surjection: every element of the output is occupied, so it can be turned back around"]', 3, 'An injection only guarantees "different inputs — different outputs". Add a surjection — there are no empty places on the output, the correspondence becomes "one to one", and an inverse function appears: encoding and decoding live on bijections.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 3, 'theory', 'Quiz: combinatorics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 3, 0, 'A PIN code consists of four digits, with 10 options at each position. Why are there exactly 10⁴ options?', '["Because the choices at the positions are independent and are multiplied by the product rule", "Because the positions are mutually exclusive and are added by the sum rule", "Because 10 is raised to a power equal to the length of the alphabet", "Because permutations of 10 digits taken 4 at a time give 10⁴"]', 0, 'The product rule: a chain of independent choices is multiplied — 10 × 10 × 10 × 10. Only mutually exclusive groups of options are added; that is the sum rule.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 3, 1, 'Gold, silver and bronze medals are awarded among 20 athletes. Which counter counts this?', '["The combination C(20, 3) — order does not matter", "An arrangement — order matters, since the medals are different", "A permutation of 20 elements", "The sum rule over the three medals"]', 1, 'A test question: if we swap two chosen items, do we get something different? The medals are different, so yes, and that is an arrangement: n!/(n−k)!. A combination would count just the trio of finalists without places.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 3, 2, 'The selection is the same, but in one case order is taken into account and in the other it is not. By how many times is the number of options with order larger?', '["By a factor of n", "By a factor of 2", "By a factor of k! — for all the permutations inside the chosen group", "By a factor of k²"]', 2, 'An arrangement turns into a combination by dividing by k!: we remove the differences between permutations inside the group. So C(n, k) is the arrangement divided by k!.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 3, 3, 'Each of 10 people in a room shakes hands with everyone else. How many handshakes are there?', '["90 — each of the ten shook hands with the nine others", "45 — pairs without repeats and mirror duplicates: C(10, 2)", "100 — ten handshakes for each of the ten", "20 — two handshakes per person"]', 1, 'A handshake is a pair in which order does not matter, so C(10, 2) = 45. This is also the number of edges of a complete graph: a hundred servers "each with each" are connected by 4950 channels.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 3, 4, 'Why will a full brute force of traveling-salesman routes for 50 cities not finish in a reasonable time?', '["Because the number of routes grows like n!: the factorial overtakes even the exponential", "Because the length of a route cannot be computed exactly", "Because the graph of cities necessarily contains cycles", "Because the problem requires sorting the cities by distance"]', 0, 'A route is a permutation of cities, and n! grows frighteningly: 10! is already more than 3.5 million, 20! is past a quintillion. That is why approximate algorithms are invented for large n instead of full brute force.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 4, 'theory', 'Quiz: the binomial theorem, Pascal and the pigeonhole principle');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 4, 0, 'What is the sum of all the numbers in row n of Pascal''s triangle?', '["n!", "n²", "2ⁿ", "C(n, n/2)"]', 2, 'Row n is all the C(n, k) in order, that is, all the subsets of an n-element set grouped by size. There are 2ⁿ subsets in total — the power set from the chapter on sets.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 4, 1, 'Where do the coefficients in the expansion of (a + b)ⁿ come from?', '["From factorials: each coefficient equals n!", "It is a row of Pascal''s triangle: the coefficient of aⁿ⁻ᵏbᵏ equals C(n, k)", "The coefficients are chosen so that their sum equals one", "From powers of two: 1, 2, 4, 8, …"]', 1, 'Raising a sum to a power means going through all the ways to place a n−k times and b k times; the number of such arrangements is C(n, k). So the coefficients of the expansion are, entire, a row of Pascal''s triangle.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 4, 2, 'Forty people started the audio course, 30 watched the webinar, and 10 did both. How many people were reached in total?', '["70", "60", "50", "80"]', 1, 'Inclusion and exclusion: |A ∪ B| = |A| + |B| − |A ∩ B| = 40 + 30 − 10 = 60. Ten people were counted twice, and the second time they are subtracted.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 4, 3, 'What exactly does the pigeonhole principle guarantee?', '["That a collision can be found in a reasonable time", "That all the cages will be occupied", "That a sufficiently good hash function can avoid collisions", "That some cage holds at least two rabbits — but it does not show which one"]', 3, 'If there are more rabbits than cages, a coincidence is guaranteed by the numbers alone. But the principle proves existence without saying where to look: we know that a pair exists, but not in which cage.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 4, 4, 'Why can collisions not be completely eliminated in a hash table?', '["Because hash functions always distribute keys badly", "Because the space of outputs is finite while there can be more elements — the pigeonhole principle guarantees coincidences", "Because memory is allocated with rounding errors", "Because keys are often similar to each other"]', 1, 'Any hash has a finite number of outputs, so with enough elements a collision must happen — not "is possible" but is guaranteed. A hash function only makes collisions rare; you have to design so that they are cheap.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 5, 'theory', 'Quiz: propositional logic');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 5, 0, 'Which of the following is NOT a proposition?', '["\"Two is greater than one\"", "\"Today is Wednesday\"", "\"What time is it?\"", "\"This disk is larger than a terabyte\""]', 2, 'A proposition is a statement that is objectively true or false. A question asserts nothing, like a command; and "this sentence is false" is a paradox that cannot be assigned either of the two values.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 5, 1, 'How does the mathematical "or" differ from the everyday one?', '["It is also true when both parts are true — it is the inclusive \"or\"", "It is false when both parts are true", "It requires exactly one part to be true", "It does not allow parentheses and precedence"]', 0, 'The mathematical "or" is inclusive: it is true if at least one part holds, including the case of both. The exclusive "or" of everyday speech is written separately in formulas.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 5, 2, 'What can be said about the statement "if 2 > 3, then I am a ballerina"?', '["It is a contradiction: the premise and the consequence are unrelated", "It is a formally true implication: the premise is false, and the contract is not violated", "It is false: the consequence is wrong", "It is not a proposition: it has no meaning"]', 1, 'With a false premise an implication is true automatically, for any consequence: the promise "rain makes the pavement wet" is not violated when there is no rain. From the same place, "all elements satisfy the condition" on an empty array honestly returns true.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 5, 3, 'How do you turn the condition "it is raining AND the wind is blowing" inside out for an early return?', '["NOT (rain OR wind)", "NOT rain AND NOT wind", "NOT rain OR NOT wind", "rain AND NOT wind"]', 2, 'De Morgan: ¬(A ∧ B) = ¬A ∨ ¬B. It is not true that both conditions hold — so at least one does not. Negation changes "and" into "or" and back.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 5, 4, 'A condition in code is true for any inputs. What is this called in terms of a truth table?', '["A contradiction — an unreachable branch", "An equivalence of two conditions", "An implication with a true premise", "A tautology — a dead check that always passes"]', 3, 'A formula that is true in all rows of the table is a tautology; in code it is a dead check. The opposite diagnosis is a contradiction, false everywhere: an unreachable branch.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 6, 'theory', 'Quiz: predicates and quantifiers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 6, 0, 'What is a predicate?', '["A statement that is true for all values of a variable", "A statement with a variable: a template that becomes true or false after a value is substituted", "A function that does not return a boolean", "A rule for deriving a new statement from two old ones"]', 1, '"x is greater than five" is neither true nor false until x is known. Substitute a value — and you get an ordinary statement. In essence it is a function returning a boolean: filter, find and if take exactly that.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 6, 1, 'How do you refute the statement "among the guests there is a vegetarian"?', '["Bring one non-vegetarian guest", "Find one more vegetarian", "Check it on half of the guests", "Show that no guest fits"]', 3, 'An existential quantifier is proved by one example and refuted only by a general argument "nobody fits". Hence the asymmetry of the work: proving that a bug exists is easy; proving that there are no bugs is a completely different conversation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 6, 2, 'A property-based test checks the property "for all generated inputs". How many failures are enough to declare the property violated?', '["None: at least thousands of green runs are needed", "Exactly half of all inputs", "One counterexample", "Only if the failure reproduced three times"]', 2, 'A "for all" statement is refuted by one counterexample — no matter how many green runs cover for it. That is why the minimal reproducing input is the main find of a failed property test.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 6, 3, 'How do you write "it is not true that every element passed the check" with quantifiers and code?', '["∀x P(x) — that is the same thing", "∃x P(x): an element that passed was found", "¬∃x ¬P(x): no failing element was found", "∃x ¬P(x): a failing element exists — some with the negated predicate"]', 3, 'De Morgan''s mirrors for quantifiers: ¬∀x P(x) = ∃x ¬P(x) and ¬∃x P(x) = ∀x ¬P(x). Negation moves inside, flipping the quantifier to the opposite one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 6, 4, 'How do the requirements "for every request there is a handler" and "there is a handler for every request" differ?', '["They don''t: the order of quantifiers does not affect the meaning", "The first is normal: each request gets its own handler; the second requires one handler for all requests at once", "The second is weaker and therefore always holds", "The first is an existential quantifier, the second a universal one, hence the difference"]', 1, 'The order of quantifiers is part of the meaning: ∀x ∃y picks its own y for each x, ∃y ∀x one y for everyone. A mixed-up order turns a normal contract into a requirement for a universal stub.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 7, 'theory', 'Quiz: induction and recurrences');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 7, 0, 'Why does induction prove a statement for all natural numbers, although only two facts are checked?', '["Because the remaining numbers are similar to the first two", "Because the chain of steps automatically carries the truth from the base to any number", "Because there are in fact finitely many natural numbers", "Because the step is checked by a program for each number separately"]', 1, 'The base gives the first step, the induction step gives the rule for stepping from any step to the next. From the two facts follows the truth on any step: the hundredth or the millionth.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 7, 1, 'How does strong induction differ from ordinary induction?', '["In the step you may rely on the truth of the statement for all numbers less than k, not only for k − 1", "It proves statements for non-integers as well", "It does not require a base", "It replaces a proof with a program check of thousands of cases"]', 0, 'An ordinary step relies on exactly k, a strong one on all the previous values at once. It is a legitimate technique: the staircase has more supporting steps; it is needed where the step depends on several previous values.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 7, 2, 'A recursive function overflows the stack. How does this sound in the language of induction?', '["There is a base, but the step is not proved for all numbers", "Too many bases — the induction does not converge", "The step is correct, but there is no base — the staircase has nothing to stand on", "It is unrelated to induction: recursion and induction are independent"]', 2, 'The base of a recursion is the base of an induction, the recursive call is the step. A missing or unreachable base breaks the first step, and the descent continues into eternity: a stack overflow is induction without a base.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 7, 3, 'Why does merge sort run in n log n?', '["Because merging two arrays costs log n", "Because the array is split into about log n levels, and the total work at each level stays linear", "Because each comparison processes log n elements", "Because recursion is always logarithmic"]', 1, 'The recurrence: the time on an array is the time on two halves plus a linear merge. There are about log n levels, and at each level the total work over all the pieces is n. In total n log n, and that is proved, not measured.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 7, 4, 'What is a loop invariant?', '["A variable whose value does not change in the loop", "The exit condition of the loop", "A statement that is true before each iteration and after each: the base before the first turn, the step across a turn", "Code executed at the start of each iteration"]', 2, 'An invariant is proved exactly by induction: true before the first turn — the base; true before a turn, so true after it — the step. The invariant plus the exit condition give correctness: this is how insertion sort and binary search are proved.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 8, 'theory', 'Quiz: graph basics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 8, 0, 'Why is the sum of the degrees of all vertices of a graph always even?', '["Because degrees are always counted in pairs", "Because each edge touches exactly two vertices and is counted twice in the sum of degrees", "Because the number of vertices is always even", "Because a graph can be drawn without self-intersections"]', 1, 'The handshake lemma: the sum of degrees equals twice the number of edges — each handshake adds one to both participants. Consequence: the number of vertices with an odd degree in any graph is even.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 8, 1, 'What kind of graph should be used for the "subscription" relation in a social network, and why?', '["Undirected: a subscription is always mutual", "Weighted: the weight of an edge is the age of the subscription", "Complete: everyone follows everyone", "Directed: a subscription can be one-sided — an arrow from the follower to the author"]', 3, 'Friendship is symmetric — it is drawn as an ordinary edge; a subscription is not symmetric — it needs an arrow. Choosing the type of graph is the first design decision: mix it up and the algorithm will answer the wrong questions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 8, 2, 'A social network with a billion users: why an adjacency list rather than a matrix?', '["Because a matrix cannot store the names of vertices", "Because the graph is sparse: a matrix would take the square of the number of vertices — a quintillion cells, while lists take space proportional to the number of edges", "Because lists automatically sort the neighbors", "Because a matrix does not support traversals"]', 1, 'Real graphs — dependencies, social ties, routes — are sparse. Lists save memory radically and give the main traversal operation "list the neighbors"; the price is scanning a list when checking a specific edge, which a matrix does in constant time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 8, 3, 'What does a cycle in a package dependency graph mean (a requires b, b requires c, c requires a)?', '["The packages will be installed in two passes", "The packages will be installed in alphabetical order", "A correct installation order does not exist: none of the cycle can be installed first, and the manager will show an error", "Nothing terrible: a cycle only slows down the installation"]', 2, 'In a dependency cycle there is no vertex to start from. A graph without cycles lets you arrange the vertices in a topological order — every arrow leads from an earlier one to a later one; that is exactly what the package manager builds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 8, 4, 'What is a connected component?', '["A subgraph in which there are no cycles", "A minimal set of edges connecting the graph", "The vertex with the maximal degree", "A piece of the graph, an \"island\": inside it everyone is reachable from everyone, and between islands there are no edges"]', 3, 'A connected graph is one piece; if there are several pieces, each is a connected component. In a social network these are communities with no mutual acquaintances, in dependencies — packages that are installed and removed only together.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 9, 'theory', 'Quiz: graph traversals and trees');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 9, 0, 'Why does any graph traversal need a set of visited vertices?', '["So that the traversal runs faster thanks to caching", "So as not to enter one vertex twice and not to loop in cycles", "To save memory on storing edges", "So that the traversal goes through the vertices in alphabetical order"]', 1, 'Without memory a traversal circles forever around one ring, like a guest without a map in a maze. The visited set is the second mandatory "organ" of a traversal alongside the rule for choosing the next vertex.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 9, 1, 'Why does breadth-first traversal find the shortest path in an unweighted graph?', '["Because the queue stores the lengths of the paths", "Because it visits vertices in alphabetical order", "Because the wave first checks all vertices at distance one, then two — by the minimal number of edges", "Because it never enters cycles at all"]', 2, 'The queue gives the "first in, first out" order, so the wave spreads in circles of distance. The stack and the queue are the only difference in the code, and the shortest-path property appears precisely with the queue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 9, 2, 'Which data structure naturally implements depth-first traversal, and why?', '["A queue: vertices are processed by circles of distance", "A stack: \"go forward while you can, hit a dead end — step back\"; with recursion its role is played by the call stack", "A hash table: a quick visited check", "A heap: the vertex with the minimal priority goes first"]', 1, 'The depth rule — "forward while you can, back one step" — is a stack: put a new node on, take a dead end off. Recursion gives it for free as the call stack, which is why any recursive stroll through a nested structure is a depth-first traversal.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 9, 3, 'How many edges does a tree with n vertices have?', '["n", "n + 1", "2n", "n − 1"]', 3, 'A tree is a connected graph without cycles, and it has exactly n − 1 edges: one vertex — zero edges, three in a chain — two. The formula works in both directions: a connected graph with n − 1 edges is necessarily a tree.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 9, 4, 'When does a graph have a path that passes along every edge exactly once (an Eulerian path)?', '["Always, if the graph is connected", "Only if all vertices have the same degree", "If the number of vertices with an odd degree is zero or two", "If the number of edges is even"]', 2, 'In the middle of a walk each visit to a vertex uses up two edges — entering and leaving, so odd degrees are allowed only at the start and the finish. Zero odd — the route closes into a circle. In Königsberg there were four — the walk is impossible.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (12, 10, 'theory', 'Quiz: probability and Bayes'' theorem');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 10, 0, 'Five coins are tossed. How many outcomes are there in total, and why?', '["10 — two options for each coin, added by the sum rule", "32 — the outcomes are independent, the product rule gives 2⁵", "25 — five coins with five options each", "120 — a permutation of five coins"]', 1, 'The coin outcomes are independent, so the options multiply: 2 × 2 × 2 × 2 × 2 = 2⁵ = 32. Classical probability is the share of favorable outcomes, and without combinatorics it cannot be computed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 10, 1, 'The events "an even number came up" and "a three came up" cannot happen at the same time. Are they dependent?', '["No: incompatibility is independence", "The question is invalid: dependence is defined only for coins", "Yes: having learned that a three came up, you know for certain that the number is not even — the information changes the estimate", "They are dependent only when rolling two dice"]', 2, 'Incompatibility is about the impossibility of happening together, dependence is about information. "A three came up" fully determines the answer about evenness, so the events are dependent, though incompatible. For independent events the probability of both is the product.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 10, 2, 'How is the conditional probability P(A | B) defined?', '["It is the product P(A) × P(B)", "It is P(A ∩ B) / P(B): the world is squeezed to the cases where B happened, and the share of A among them is taken", "It is P(A ∪ B) − P(A)", "It is the probability of A minus the probability of B"]', 1, 'The condition B works as a filter: we consider only the world where B happened and recalculate the share of A in that narrowed world. It is cloudy — the probability of rain is higher, although the climate is the same.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 10, 3, 'A disease is rare (1 in 1000), the test catches the sick in 99% of cases and wrongly flags 1% of the healthy. Why is the disease still unlikely after a positive test?', '["Because the test must be repeated three times", "Because 99% is a low accuracy for medical tests", "Because the disease does not obey probability", "Because there are too many healthy people: thousands of false positives outweigh a hundred true ones — base rate neglect"]', 3, 'Out of a hundred thousand people there will be about a hundred sick people caught and about a thousand healthy people falsely flagged. A positive result more often means an error than a disease — this is not a defect of the test but the power of the base rate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (12, 10, 4, 'What does Bayes'' formula do?', '["Proves that two random variables are independent", "Turns the condition around: updates confidence in a cause when evidence appears — the prior frequency is multiplied by the likelihood of the effect", "Guarantees a cache hit at the right size", "Computes probability without regard to prior data"]', 1, 'The probability of a cause given an observed effect is proportional to the likelihood of the effect given the cause, multiplied by the prior frequency of the cause. This is how spam filters and incident diagnostics work: updating confidence word by word, alert by alert.');
